<?php
declare(strict_types=1);
namespace QualitySystem\Tests;
use PHPUnit\Framework\TestCase;use QualitySystem\Security\PermissionMatrix;
final class ProgramManualAuthorizationTest extends TestCase{
    public function testManualPermissionsFollowProgramGovernance():void{$this->assertTrue(PermissionMatrix::allows('Reviewer','program_manuals','view'));$this->assertFalse(PermissionMatrix::allows('Reviewer','program_manuals','create'));$this->assertTrue(PermissionMatrix::allows('Program Leader','program_manuals','update'));$this->assertFalse(PermissionMatrix::allows('Program Leader','program_manuals','delete'));$this->assertTrue(PermissionMatrix::allows('Admin','program_manuals','delete'));}
    public function testOnlyQualityGovernanceRolesApproveReconciliation():void{$this->assertTrue(PermissionMatrix::allows('Admin','program_manuals','approve'));$this->assertTrue(PermissionMatrix::allows('Quality Coordinator','program_manuals','approve'));$this->assertFalse(PermissionMatrix::allows('Program Leader','program_manuals','approve'));$this->assertFalse(PermissionMatrix::allows('Reviewer','program_manuals','approve'));}
    public function testRouterOwnsUniversalManualRoutes():void{$source=file_get_contents(dirname(__DIR__).'/app/Http/CompatibilityRouter.php');$this->assertStringContainsString("'/program-manuals'",$source);$this->assertStringContainsString('ProgramManualController',$source);}
    public function testAutomationEndpointRequiresScopedManualPermissions():void{$source=file_get_contents(dirname(__DIR__).'/program_manual_automation.php');$this->assertStringContainsString("require_once __DIR__.'/auth_check.php'",$source);$this->assertStringContainsString("'program_manuals','update'",$source);}
    public function testMappingReviewRequiresAuthenticationCsrfAndProgramScope():void{$source=file_get_contents(dirname(__DIR__).'/program_manual_mapping_review.php');$this->assertStringContainsString("require_once __DIR__.'/auth_check.php'",$source);$this->assertStringContainsString("PermissionMatrix::allows",$source);$this->assertStringContainsString('program_specification_id', $source);$this->assertStringContainsString('csrfField()', $source);}
    public function testMigrationUsesProtectedStorageMetadataAndForeignKeys():void{$source=file_get_contents(dirname(__DIR__).'/database/migrations/20260828_009_program_manuals.php');$this->assertStringContainsString('source_storage_key',$source);$this->assertStringContainsString('source_sha256',$source);$this->assertStringContainsString('program_manual_sections',$source);$this->assertStringContainsString('FOREIGN KEY(program_specification_id)',$source);}
}
